static const uint8_t *glyph_columns(char character) {
	for (size_t i = 0; i < sizeof(font) / sizeof(font[0]); ++i) {
		if (font[i].character == character) {
			return font[i].columns;
		}
	}
	return font[sizeof(font) / sizeof(font[0]) - 1].columns;
}
